const p=$input.first().json;const raw=p.raw_data||p;
const discovery=new Date(raw.discovery_time||Date.now());
const deadline72h=new Date(discovery.getTime()+72*3600000);
const now=new Date();
const hoursRemaining=Math.round((deadline72h-now)/3600000);

// GDPR Article 33 threshold: 250+ records OR sensitive categories always notifiable
const SENSITIVE_CATEGORIES=['health','biometric','financial','children','criminal','political','religious'];
const hasSensitive=(raw.affected_data_categories||[]).some(c=>SENSITIVE_CATEGORIES.includes(c.toLowerCase()));
const mustNotify=parseInt(raw.affected_records||0)>=250||hasSensitive||raw.force_notify===true;

return[{json:{_breach_id:`GDPR-${Date.now()}`,_discovered_at:discovery.toISOString(),_deadline_72h:deadline72h.toISOString(),_hours_remaining:hoursRemaining,_must_notify:mustNotify,breach_type:raw.breach_type||'unauthorized_access',affected_records:parseInt(raw.affected_records||0),affected_data_categories:raw.affected_data_categories||[],systems_affected:raw.systems_affected||[],discovered_by:raw.discovered_by||'automated',description:raw.description||'Data breach detected',has_sensitive_data:hasSensitive,risk_to_individuals:hasSensitive||raw.affected_records>1000?'High':'Medium'}}];}

